"""Non-root handover service and human CLI over the shared coordinator.

Installed configuration is root-owned; operator requests are root-owned files,
not phone comments or caller-asserted roles. Live activation remains separate.
"""
import argparse
from datetime import datetime,timezone
import hashlib
import json
import os
from pathlib import Path
import socket
import stat
import sqlite3

from orchestrator.handover_coordinator import Coordinator,encoded,digest
from orchestrator.operations_report import finalize,Queue,immutable
from orchestrator.remote_supervisor import checked_source
from orchestrator.public_export import text


def configuration(path):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
    try:
        info=os.fstat(fd)
        if info.st_uid!=0 or info.st_mode & 0o022 or not stat.S_ISREG(info.st_mode) or info.st_size>65536:raise ValueError('INSTALLED_CONFIG_REQUIRED')
        return json.loads(os.read(fd,65536))
    finally:os.close(fd)


def request_broker(path,operation,body):
    raw=encoded({'operation':operation,'body':body});text(raw.decode(),limit=1500000)
    with socket.socket(socket.AF_UNIX,socket.SOCK_STREAM) as client:
        client.settimeout(300);client.connect(path);client.sendall(raw)
        result=b''
        while not result.endswith(b'\n'):
            chunk=client.recv(65536)
            if not chunk or len(result)+len(chunk)>1500000:raise ValueError('BROKER_RESPONSE_UNAVAILABLE')
            result+=chunk
    value=json.loads(result)
    if value.get('status')=='REFUSED':raise ValueError('BROKER_REFUSED_RECONCILE')
    return value


class Runtime:
    def __init__(self,config):
        self.config=config
        self.root=checked_source(config['source_root'],config['source'])
        if os.getuid()!=config['controller_uid']:raise ValueError('NONROOT_CONTROLLER_IDENTITY_REQUIRED')
        self.state=Path(config['state'])
        self.q=Coordinator(self.state,{'continuation':self.model,'review':self.model,'disposition':self.model},self.admit,self.validate_binding)
        self.q.db.executescript('''
            CREATE TABLE IF NOT EXISTS bookkeeping(task TEXT PRIMARY KEY,status TEXT,attempts INTEGER,reason TEXT);
            CREATE TABLE IF NOT EXISTS control_delivery(id TEXT PRIMARY KEY,outcome TEXT);
            CREATE TABLE IF NOT EXISTS runtime_blocks(phase TEXT PRIMARY KEY,reason TEXT);
        ''')
        self.completions=None
        if config.get('synthetic_execution') is not None:
            from orchestrator.completion_bridge import CompletionBridge
            self.completions=CompletionBridge(self,config['synthetic_execution'])

    @staticmethod
    def validate_binding(binding):
        if binding['stages']!=['continuation','review','disposition']:
            raise ValueError('CANONICAL_REPORT_STAGES_REQUIRED')

    def event(self,binding):
        return {'turn_id':binding['id'],'attempt':'1','source':binding['source'],
                'branch':'astra/infrastructure-milestone-record','kind':binding['kind']}

    def admit(self,binding):
        return request_broker(self.config['broker_socket'],'admit_server',self.event(binding))

    def model(self,binding,position):
        task_root=self.state/'tasks'/binding['id']
        raw=(task_root/'packet.json').read_bytes();packet=json.loads(raw)
        # Task ID includes the complete immutable packet, source, and report identity.
        expected=digest({'source':binding['source'],'packet':packet,'report':json.loads((task_root/'report.json').read_text())})
        if expected!=binding['id']:raise ValueError('TASK_PACKET_CHANGED')
        report=json.loads((task_root/'report.json').read_text())
        report_root=self.state/'reports'
        report_text=(report_root/(report['id']+'.md')).read_text()
        if hashlib.sha256(report_text.encode()).hexdigest()!=report['id']:raise ValueError('REPORT_CHANGED')
        self.validate_binding(binding)
        stage=binding['stages'][position]
        prompt={'continuation':'Assess this report against approved goals, identify the next eligible task and limits. Do not execute or grant authority.',
                'review':'Fresh Claude primary-evidence review under the supplied directive. Assess science, implementation and human operation; distinguish verified evidence and missing proof. Do not infer nonexistent evidence from omission.',
                'disposition':'Record Astra disposition of the existing fresh review and the next eligible bounded task. No execution or ratification.'}[stage]
        proposal=packet.get('execution_proposal')
        if proposal is not None:
            prompt+=' The installed supervised configuration offers exactly one synthetic successor; review its eligibility and boundaries.'
            if stage=='disposition':
                prompt=('Record your response to the fresh review and select the configured synthetic successor. '
                        'Return exactly one JSON object with task_id equal to '+proposal['job']+
                        ' and reason containing your review disposition and rationale; if a blocking concern remains, '
                        'use task_id null and explain it in reason. The system validates the selection '
                        'before submission. Do not select patient work, a different job or a new scope.')
        prompt+='\nREPORT:\n'+report_text+'\nPRIMARY EVIDENCE:\n'+json.dumps(packet)
        for previous in ['continuation','review'][:position]:
            prior=self.q._receipt(binding['id'],['continuation','review'].index(previous),binding)
            if prior is None:raise ValueError('PREDECESSOR_RECEIPT_REQUIRED')
            prompt+='\n'+previous.upper()+':\n'+prior['output']['answer']
        response=request_broker(self.config['broker_socket'],'model_stage',{'event':self.event(binding),'stage':stage,'packet':packet,'prompt':prompt})
        if response.get('status')!='COMPLETE':raise ValueError('MODEL_COMPLETION_REQUIRED')
        return response

    def enqueue_report(self,day,receipts,task_state,reviewer_evidence=None,execution_proposal=None,trigger='scheduled-report'):
        if trigger not in ('scheduled-report','verified-completion'):raise ValueError('REPORT_TRIGGER_REQUIRED')
        finalized=finalize(self.state/'reports',self.config['source'],day,receipts,task_state=task_state)
        report={'id':finalized['id']}
        packet={'jobs':receipts,'trigger':trigger,'decision_inbox':task_state}
        if reviewer_evidence is not None:packet['reviewer_evidence']=reviewer_evidence
        if execution_proposal is not None:packet['execution_proposal']=execution_proposal
        identity=digest({'source':self.config['source'],'packet':packet,'report':report})
        directory=self.state/'tasks'/identity;directory.mkdir(parents=True,mode=0o700,exist_ok=True)
        immutable(directory/'packet.json',encoded(packet));immutable(directory/'report.json',encoded(report))
        return {'id':identity,'source':self.config['source'],'kind':'nightly_review','thread':'adjacent',
                'dependencies':[],'stages':['continuation','review','disposition']}

    def bookkeeping(self):
        # Capped, per-task finalization. Completed or blocked entries do not rescan
        # model artifacts forever; scientific/model execution is never retried here.
        rows=self.q.db.execute("""SELECT t.id FROM tasks t LEFT JOIN bookkeeping b ON t.id=b.task
            WHERE t.status='COMPLETE' AND (b.status IS NULL OR b.status='RETRY') LIMIT 32""").fetchall()
        for row in rows:
            prior=self.q.db.execute('SELECT attempts FROM bookkeeping WHERE task=?',(row['id'],)).fetchone()
            attempt=(prior[0] if prior else 0)+1
            try:
                self._bookkeep(row)
                status,reason='COMPLETE',None
            except (ValueError,KeyError,TypeError,OSError,sqlite3.Error):
                status='BLOCKED' if attempt>=3 else 'RETRY'
                reason='BOOKKEEPING_EVIDENCE_PRESERVED'
                # A failed attachment must not leave a claimed review pretending
                # it is still running. Preserve its actual original review files.
                try:
                    report=json.loads((self.state/'tasks'/row['id']/'report.json').read_text())
                    queue=Queue(self.state/'reports');claim=queue.status(report['id'])
                    if claim['status']=='REVIEWING':queue.unavailable(report['id'],claim['attempt_id'],'bookkeeping-preserved')
                except (ValueError,KeyError,TypeError,OSError,sqlite3.Error):pass
            self.q.db.execute('INSERT OR REPLACE INTO bookkeeping VALUES(?,?,?,?)',(row['id'],status,attempt,reason))

    def _bookkeep(self,row):
        folder=self.state/'tasks'/row['id'];report=json.loads((folder/'report.json').read_text())
        queue=Queue(self.state/'reports');status=queue.status(report['id'])
        binding=json.loads(self.q.db.execute('SELECT binding FROM tasks WHERE id=?',(row['id'],)).fetchone()[0])
        review=self.q._receipt(row['id'],1,binding)['output']
        if status['status']!='REVIEWED':
            claim=status if status['status']=='REVIEWING' else queue.claim(report['id'])
            if not claim:raise ValueError('REVIEW_BOOKKEEPING_CLAIM_REQUIRED')
            r=review['receipt'];answer=review['answer']
            queue.attach(report['id'],claim['attempt_id'],answer,{'family':'claude','model':r['actual_model'],'source':self.config['source'],
                'report_sha256':report['id'],'review_sha256':hashlib.sha256(answer.encode()).hexdigest(),
                'execution_receipt_sha256':hashlib.sha256((json.dumps(r,sort_keys=True,indent=2)+'\n').encode()).hexdigest(),
                'session_id':r['session_id'],'status':'COMPLETE'})
        disposition=self.q._receipt(row['id'],2,binding)['output']['answer']
        queue.disposition(report['id'],disposition)
        if self.completions is not None:
            self.completions.finish(row['id'],json.loads((folder/'packet.json').read_text()),disposition)


    def controls(self):
        results=[]
        directory=Path(self.config['control_inbox'])
        if directory.is_symlink() or directory.stat().st_uid!=0 or directory.stat().st_mode & 0o022:
            raise ValueError('PROTECTED_CONTROL_INBOX')
        for path in sorted(directory.glob('*.json')):
            if len(path.stem)!=64 or any(c not in '0123456789abcdef' for c in path.stem):
                continue
            receipt=self.state/('control-'+path.stem+'.json')
            if self.q.db.execute('SELECT 1 FROM control_delivery WHERE id=?',(path.stem,)).fetchone():continue
            try:
                request=configuration(path)
                if set(request)!={'source','control'} or request['source']!=self.config['source']:
                    raise ValueError('STALE_CONTROL_SOURCE')
                result=self.q.control(request['control'],authenticated_operator=True)
                outcome={'status':'APPLIED','request':path.stem,'revision':result['revision']}
            except (ValueError,KeyError,TypeError,OSError,sqlite3.Error):
                outcome={'status':'BLOCKED','request':path.stem,
                    'reason':'CONTROL_INVALID_OR_STALE','next_action':'Submit a new operator request bound to current source and control revision.'}
            try:immutable(receipt,encoded(outcome))
            except (ValueError,OSError):
                outcome={**outcome,'receipt_status':'WRITE_BLOCKED','next_action':'Preserve the SQLite control record and repair the receipt destination.'}
            self.q.db.execute('INSERT OR IGNORE INTO control_delivery VALUES(?,?)',(path.stem,encoded(outcome).decode()))
            results.append(outcome)
        return results

    def scheduled_report(self,now):
        """Explicit installed schedule; deterministic polling spends no model call."""
        from zoneinfo import ZoneInfo
        schedule=self.config.get('report_schedule')
        if schedule is None:return {'status':'SCHEDULE_DISABLED'}
        if set(schedule)!={'zone','hour','minute','evidence_file'}:raise ValueError('SCHEDULE_SCHEMA')
        local=now.astimezone(ZoneInfo(schedule['zone']))
        if (local.hour,local.minute)<(schedule['hour'],schedule['minute']):return {'status':'NOT_DUE'}
        day=local.date().isoformat()
        prior=self.q.db.execute('SELECT task FROM schedules WHERE day=?',(day,)).fetchone()
        if prior:return {'status':'ALREADY_SCHEDULED','task':prior[0]}
        evidence=configuration(schedule['evidence_file'])
        if set(evidence) not in ({'source','receipts','task_state'},{'source','receipts','task_state','reviewer_evidence'}) or evidence['source']!=self.config['source']:raise ValueError('REPORT_EVIDENCE_SOURCE')
        # Installed evidence is a supplied snapshot, not a live queue census.
        # Capture current coordinator state in the same transaction used for
        # daily identity creation. Never read prompts or private job payloads.
        self.q.db.execute('BEGIN IMMEDIATE')
        try:
            state=self.q.status()
            task_state=dict(evidence['task_state'])
            task_state['coordinator_observed_at']=now.isoformat()
            priority={'RUNNING':0,'BLOCKED':1,'QUEUED':2,'COMPLETE':3}
            selected=sorted(state['tasks'],key=lambda row:(priority.get(row['status'],4),row['id']))[:24]
            task_state['coordinator_tasks']=[{**row,'reason':row['reason'] if row['reason'] is None or len(row['reason'])<=256
                else 'REASON_TOO_LONG_SEE_PRIVATE_TASK_RECORD'} for row in selected]
            task_state['coordinator_tasks_total']=len(state['tasks'])
            task_state['coordinator_tasks_omitted']=len(state['tasks'])-len(selected)
            task_state['coordinator_control']={'revision':state['revision'],'paused':bool(state['paused'])}
            task_state['evidence_scope']='Installed evidence plus current coordinator metadata; not a census of other execution queues.'
            task_state['coordinator_summary']=', '.join(
                str(sum(row['status']==status for row in state['tasks']))+' '+status.lower()
                for status in ('QUEUED','RUNNING','COMPLETE','BLOCKED'))
            if self.completions is not None:
                task_state['completion_blocks']=[dict(row) for row in self.q.db.execute('SELECT * FROM completion_blocks')]
                task_state['selected_work']=[dict(row) for row in self.q.db.execute('SELECT task,status,attempts FROM selected_dispatch')]
            binding=self.enqueue_report(day,evidence['receipts'],task_state,evidence.get('reviewer_evidence'))
        finally:
            self.q.db.execute('ROLLBACK')
        # schedule owns its transaction. Concurrent callers converge on the
        # already-persisted day; an unused immutable snapshot grants no authority.
        return self.q.schedule(now,schedule['zone'],schedule['hour'],schedule['minute'],binding)

    def recover(self):
        outcomes=[]
        def retrieve(binding,position):
            return request_broker(self.config['broker_socket'],'stage_status',
                {'event':self.event(binding),'stage':binding['stages'][position]})
        for row in self.q.status()['tasks']:
            if row['status'] in ('BLOCKED','RUNNING'):
                try:outcomes.append(self.q.recover(row['id'],retrieve))
                except (ValueError,KeyError,TypeError,OSError,sqlite3.Error):
                    self.q.db.execute("UPDATE tasks SET status='BLOCKED',reason='RECOVERY_EVIDENCE_UNAVAILABLE' WHERE id=?",(row['id'],))
        return outcomes

    def tick(self):
        for name,operation in [('controls',self.controls),('recovery',self.recover),
                               ('completions',lambda:self.completions.ingest() if self.completions else None),
                               ('selected-work',lambda:self.completions.advance() if self.completions else None),
                               ('schedule',lambda:self.scheduled_report(datetime.now(timezone.utc)))]:
            try:
                operation()
                self.q.db.execute('DELETE FROM runtime_blocks WHERE phase=?',(name,))
            except (ValueError,KeyError,TypeError,OSError,sqlite3.Error):
                self.q.db.execute('INSERT OR REPLACE INTO runtime_blocks VALUES(?,?)',(name,'EVIDENCE_OR_CONFIGURATION_REQUIRES_RECONCILIATION'))
        control_block=self.q.db.execute("SELECT 1 FROM runtime_blocks WHERE phase='controls'").fetchone()
        result={'status':'CONTROL_TRANSPORT_BLOCKED'} if control_block else self.q.tick()
        self.bookkeeping()
        return result

    def status(self):
        return {**self.q.status(),
                'completion_events':[] if self.completions is None else [dict(row) for row in self.q.db.execute('SELECT * FROM completion_ingest')],
                'selected_work':[] if self.completions is None else [dict(row) for row in self.q.db.execute('SELECT task,status,attempts FROM selected_dispatch')],
                'completion_blocks':[] if self.completions is None else [dict(row) for row in self.q.db.execute('SELECT * FROM completion_blocks')],
                'runtime_blocks':[dict(row) for row in self.q.db.execute('SELECT * FROM runtime_blocks')],
                'bookkeeping':[dict(row) for row in self.q.db.execute('SELECT * FROM bookkeeping')],
                'controls':[json.loads(row[0]) for row in self.q.db.execute('SELECT outcome FROM control_delivery')]}


def operator_request(config,action,revision,request_id):
    if os.getuid()!=0:raise ValueError('OPERATOR_ADMIN_REQUIRED')
    directory=Path(config['control_inbox'])
    if directory.is_symlink() or directory.stat().st_uid!=0 or directory.stat().st_mode & 0o022:raise ValueError('PROTECTED_CONTROL_INBOX')
    request={'source':config['source'],'control':{'id':request_id,'expected_revision':revision,'action':action}}
    # Numeric/hash-derived filename; no user-controlled traversal.
    path=directory/(digest(request)+'.json')
    immutable(path,encoded(request));os.chown(path,0,config['controller_gid']);os.chmod(path,0o640)
    return {'status':'REQUESTED_NOT_YET_APPLIED','request':digest(request)}


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--config',required=True)
    p.add_argument('operation',choices=['tick','status','controls','pause','resume'])
    p.add_argument('--revision',type=int);p.add_argument('--request-id')
    a=p.parse_args();config=configuration(a.config)
    if a.operation in ('pause','resume'):
        if a.revision is None or not a.request_id:p.error('pause/resume require --revision and --request-id')
        result=operator_request(config,a.operation,a.revision,a.request_id)
    else:
        runtime=Runtime(config)
        result=runtime.status() if a.operation=='status' else (runtime.tick() if a.operation=='tick' else runtime.controls())
    print(text(json.dumps(result)))


if __name__=='__main__':main()

"""Persistent bounded coordinator over Store, with immutable stage completion.

Handlers are installed Python interfaces, never request-selected shell commands.
A missing completion after STARTED is uncertain: preserve and block that task.
Already completed stages (including Claude review) are never rerun for bookkeeping.
"""
from contextlib import contextmanager
from datetime import datetime
import fcntl
import hashlib
import json
import os
from pathlib import Path
import sqlite3

from orchestrator.job_store import Store
from orchestrator.operations_report import private_root, immutable
from orchestrator.public_export import text


def encoded(value): return (json.dumps(value,sort_keys=True)+'\n').encode()
def digest(value): return hashlib.sha256(encoded(value)).hexdigest()


class Coordinator:
    def __init__(self,root,handlers,admission,validate_binding=None):
        self.root=private_root(root)
        self.store=Store(self.root/'coordinator.sqlite');self.db=self.store.db
        self.handlers=handlers;self.admission=admission
        self.validate_binding=validate_binding or (lambda binding: None)
        self.db.executescript('''
          CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,binding TEXT NOT NULL,status TEXT NOT NULL,reason TEXT);
          CREATE TABLE IF NOT EXISTS stages(task TEXT,position INTEGER,state TEXT NOT NULL,receipt TEXT,PRIMARY KEY(task,position));
          CREATE TABLE IF NOT EXISTS controls(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER,paused INTEGER);
          INSERT OR IGNORE INTO controls VALUES(1,0,0);
          CREATE TABLE IF NOT EXISTS steering(id TEXT PRIMARY KEY,binding TEXT NOT NULL);
          CREATE TABLE IF NOT EXISTS schedules(day TEXT PRIMARY KEY,task TEXT NOT NULL);
        ''')

    def submit(self,binding):
        required={'id','source','kind','thread','dependencies','stages'}
        if set(binding)!=required or binding['thread'] not in ('primary','adjacent') or binding['kind'] not in ('astra_turn','nightly_review'):
            raise ValueError('TASK_SCHEMA')
        if not isinstance(binding['id'],str) or len(binding['id'])!=64 or any(c not in '0123456789abcdef' for c in binding['id']):raise ValueError('TASK_ID')
        if len(binding['source'])!=40 or any(c not in '0123456789abcdef' for c in binding['source']):raise ValueError('SOURCE_ID')
        if not 1<=len(binding['stages'])<=3 or any(s not in self.handlers for s in binding['stages']):raise ValueError('BOUNDED_INSTALLED_HANDLERS_REQUIRED')
        if len(binding['dependencies'])>32 or binding['id'] in binding['dependencies']:raise ValueError('DEPENDENCIES')
        self.validate_binding(binding)
        raw=encoded(binding).decode();text(raw)
        inserted=self.db.execute('INSERT OR IGNORE INTO tasks VALUES(?,?,?,NULL)',(binding['id'],raw,'QUEUED')).rowcount
        old=self.db.execute('SELECT binding FROM tasks WHERE id=?',(binding['id'],)).fetchone()
        if old[0]!=raw:raise ValueError('TASK_BINDING_CONFLICT')
        return {'duplicate':not bool(inserted),'id':binding['id']}

    def status(self):
        control=dict(self.db.execute('SELECT revision,paused FROM controls').fetchone())
        return {**control,'tasks':[dict(r) for r in self.db.execute('SELECT id,status,reason FROM tasks ORDER BY id')]}

    def control(self,request,*,authenticated_operator):
        with (self.root/'admission.lock').open('a') as gate:
            fcntl.flock(gate,fcntl.LOCK_EX)
            return self._control(request,authenticated_operator=authenticated_operator)

    def _control(self,request,*,authenticated_operator):
        # Only a trusted transport can supply authenticated_operator. No JSON role
        # or phone ACK is an authentication mechanism.
        if not authenticated_operator:raise ValueError('OPERATOR_AUTH_REQUIRED')
        if set(request)!={'id','expected_revision','action'} or request['action'] not in ('pause','resume'):raise ValueError('CONTROL_SCHEMA')
        text(json.dumps(request));raw=encoded(request).decode()
        self.db.execute('BEGIN IMMEDIATE')
        try:
            previous=self.db.execute('SELECT binding FROM steering WHERE id=?',(request['id'],)).fetchone()
            if previous:
                if previous[0]!=raw:raise ValueError('STEERING_CONFLICT')
                self.db.execute('COMMIT');return {'duplicate':True,**self.status()}
            rev=self.db.execute('SELECT revision FROM controls').fetchone()[0]
            if request['expected_revision']!=rev:raise ValueError('STALE_CONTROL')
            self.db.execute('INSERT INTO steering VALUES(?,?)',(request['id'],raw))
            self.db.execute('UPDATE controls SET revision=revision+1,paused=?',(request['action']=='pause',))
            self.db.execute('COMMIT')
        except BaseException:self.db.execute('ROLLBACK');raise
        return {'duplicate':False,**self.status()}

    def schedule(self,now,zone,hour,minute,binding):
        from zoneinfo import ZoneInfo
        if now.tzinfo is None or not 0<=hour<24 or not 0<=minute<60:raise ValueError('EXPLICIT_SCHEDULE_REQUIRED')
        local=now.astimezone(ZoneInfo(zone))
        if (local.hour,local.minute)<(hour,minute):return {'status':'NOT_DUE'}
        if binding['kind']!='nightly_review':raise ValueError('NIGHTLY_KIND')
        day=local.date().isoformat()
        # Caller derives report/task identity from day + pinned report. Review and
        # disposition publication cannot recursively create a new schedule day.
        self.db.execute('BEGIN IMMEDIATE')
        try:
            prior=self.db.execute('SELECT task FROM schedules WHERE day=?',(day,)).fetchone()
            if prior:
                self.db.execute('COMMIT');return {'status':'ALREADY_SCHEDULED','task':prior[0]}
            self.submit(binding)
            self.db.execute('INSERT INTO schedules VALUES(?,?)',(day,binding['id']))
            self.db.execute('COMMIT')
        except BaseException:self.db.execute('ROLLBACK');raise
        return {'status':'SCHEDULED','task':binding['id']}

    def _receipt(self,task,position,binding):
        path=self.root/(task+'-'+str(position)+'.json')
        if not path.exists():return None
        if path.is_symlink():raise ValueError('STAGE_RECEIPT_SYMLINK')
        value=json.loads(path.read_text())
        if set(value)!={'binding','position','output','output_sha256'} or value['binding']!=digest(binding) or value['position']!=position or digest(value['output'])!=value['output_sha256']:raise ValueError('STAGE_RECEIPT_CHANGED')
        text(json.dumps(value));return value

    def recover(self, task, retrieve):
        """Recover only original outcomes through an installed read-only handler.

        Unknown execution stays blocked. Never turn absence into a retry decision.
        """
        with (self.root/'branch.lock').open('a') as lock:
            fcntl.flock(lock,fcntl.LOCK_EX)
            row=self.db.execute('SELECT * FROM tasks WHERE id=?',(task,)).fetchone()
            if not row:raise ValueError('UNKNOWN_TASK')
            binding=json.loads(row['binding'])
            for stage in self.db.execute('SELECT position FROM stages WHERE task=?',(task,)).fetchall():
                position=stage[0]
                if self._receipt(task,position,binding) is not None:continue
                output=retrieve(binding,position)
                if output.get('status')!='COMPLETE':
                    reason='NOT_STARTED_RECONCILIATION_REQUIRED' if output.get('status')=='NOT_STARTED_RECONCILIATION_REQUIRED' else 'UNCERTAIN_STAGE_RECONCILE_NO_RETRY'
                    self.db.execute("UPDATE tasks SET status='BLOCKED',reason=? WHERE id=?",(reason,task))
                    return {'status':reason}
                value={'binding':digest(binding),'position':position,'output':output,'output_sha256':digest(output)}
                immutable(self.root/(task+'-'+str(position)+'.json'),encoded(value))
            if row['status']!='COMPLETE':
                self.db.execute("UPDATE tasks SET status='QUEUED',reason=NULL WHERE id=?",(task,))
            return {'status':'RECOVERED','model_calls':0}

    def reconcile(self,task):
        with (self.root/'branch.lock').open('a') as lock:
            fcntl.flock(lock,fcntl.LOCK_EX)
            row=self.db.execute('SELECT * FROM tasks WHERE id=?',(task,)).fetchone()
            if not row:raise ValueError('UNKNOWN_TASK')
            binding=json.loads(row['binding'])
            for stage in self.db.execute('SELECT position FROM stages WHERE task=?',(task,)):
                if self._receipt(task,stage[0],binding) is None:
                    return {'status':'UNCERTAIN_STAGE_RECONCILE_NO_RETRY'}
            if row['status']!='COMPLETE':
                self.db.execute("UPDATE tasks SET status='QUEUED',reason=NULL WHERE id=?",(task,))
            return {'status':'RECONCILED','model_calls':0}

    def tick(self):
        with (self.root/'branch.lock').open('a') as lock:
            try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:return {'status':'WRITER_BUSY'}
            if self.status()['paused']:return {'status':'PAUSED'}
            for row in self.db.execute("SELECT * FROM tasks WHERE status IN ('QUEUED','RUNNING') ORDER BY rowid").fetchall():
                task=row['id'];binding=json.loads(row['binding'])
                self.validate_binding(binding)
                deps=[self.db.execute('SELECT status FROM tasks WHERE id=?',(d,)).fetchone() for d in binding['dependencies']]
                if any(not d or d[0]!='COMPLETE' for d in deps):
                    self.db.execute("UPDATE tasks SET reason='WAITING_DEPENDENCIES' WHERE id=?",(task,));continue
                with (self.root/'admission.lock').open('a') as gate:
                    fcntl.flock(gate,fcntl.LOCK_EX)
                    if self.status()['paused']:return {'status':'PAUSED'}
                    try:admitted=self.admission(binding)
                    except (ValueError,OSError):
                        self.db.execute("UPDATE tasks SET reason='ADMISSION_UNAVAILABLE' WHERE id=?",(task,))
                        continue
                if admitted['status']!='ADMITTED':
                    self.db.execute("UPDATE tasks SET reason=? WHERE id=?",(admitted['status'],task));continue
                for position,handler in enumerate(binding['stages']):
                    prior=self.db.execute('SELECT state FROM stages WHERE task=? AND position=?',(task,position)).fetchone()
                    receipt=self._receipt(task,position,binding)
                    if receipt:
                        self.db.execute("INSERT OR REPLACE INTO stages VALUES(?,?,'COMPLETE',?)",(task,position,digest(receipt)));continue
                    if prior:
                        self.db.execute("UPDATE tasks SET status='BLOCKED',reason='UNCERTAIN_STAGE_RECONCILE_NO_RETRY' WHERE id=?",(task,));break
                    self.db.execute("INSERT INTO stages VALUES(?,?,'STARTED',NULL)",(task,position))
                    self.db.execute("UPDATE tasks SET status='RUNNING',reason=NULL WHERE id=?",(task,))
                    try:
                        output=self.handlers[handler](binding,position)
                        value={'binding':digest(binding),'position':position,'output':output,'output_sha256':digest(output)}
                        immutable(self.root/(task+'-'+str(position)+'.json'),encoded(value))
                    except Exception:
                        self.db.execute("UPDATE tasks SET status='BLOCKED',reason='STAGE_FAILED_OR_UNCERTAIN_PRESERVED' WHERE id=?",(task,));break
                    self.db.execute("UPDATE stages SET state='COMPLETE',receipt=? WHERE task=? AND position=?",(digest(value),task,position))
                else:
                    self.db.execute("UPDATE tasks SET status='COMPLETE',reason=NULL WHERE id=?",(task,))
                return {'status':self.db.execute('SELECT status FROM tasks WHERE id=?',(task,)).fetchone()[0],'task':task}
            return {'status':'WAITING_FOR_ELIGIBLE_WORK'}

"""Bounded synthetic completion routing through the existing Linux controller.

Installed configuration chooses at most two predecessor/successor pairs. Models
can select only the configured synthetic successor, never a command, patient
runner, backend, source or threshold. Original events and console identities are
verified before a report task is submitted. Intent precedes idempotent submission;
missing execution evidence never becomes a new attempt.
"""
from datetime import datetime,timezone
import json
import sqlite3
from pathlib import Path

from orchestrator.handover_coordinator import encoded,digest
from orchestrator.hosted_cycle import verified_jobs,select_next
from orchestrator.operations_report import immutable
from orchestrator.remote_supervisor import Controller,checked_source,identifier,lock
from orchestrator.reviewer_evidence import collect,current_process


class CompletionBridge:
    def __init__(self,runtime,config):
        if (set(config)!={'authority','source','source_root','state','outputs','pairs'}
                or config['authority']!='OPERATOR_SUPERVISED_SYNTHETIC_ONLY'
                or not isinstance(config['pairs'],dict) or not 1<=len(config['pairs'])<=2):
            raise ValueError('BOUNDED_SYNTHETIC_COMPLETION_CONFIGURATION')
        names=list(config['pairs'])+list(config['pairs'].values())
        for name in names:identifier(name)
        if len(set(names))!=len(names):raise ValueError('SYNTHETIC_COMPLETION_CYCLE_OR_DUPLICATE')
        checked_source(config['source_root'],config['source'])
        self.runtime=runtime;self.config=config
        self.controller=Controller(Path(config['state'])/'jobs.sqlite')
        runtime.q.db.executescript('''
            CREATE TABLE IF NOT EXISTS completion_ingest(event TEXT PRIMARY KEY,job TEXT UNIQUE,task TEXT UNIQUE,status TEXT);
            CREATE TABLE IF NOT EXISTS selected_dispatch(task TEXT PRIMARY KEY,binding TEXT,status TEXT,attempts INTEGER DEFAULT 0);
            CREATE TABLE IF NOT EXISTS completion_blocks(job TEXT PRIMARY KEY,reason TEXT);
        ''')

    def ingest(self):
        r=self.runtime
        allowed={**self.config['pairs'],**{name:None for name in self.config['pairs'].values()}}
        for job,next_job in allowed.items():
            prior=r.q.db.execute('SELECT event FROM completion_ingest WHERE job=?',(job,)).fetchone()
            if prior:
                observed=self.controller.db.execute('SELECT id FROM linux_attempts WHERE job=?',(job,)).fetchone()
                if not observed or observed[0]!=prior['event']:
                    r.q.db.execute('INSERT OR REPLACE INTO completion_blocks VALUES(?,?)',
                        (job,'COMPLETION_IDENTITY_CHANGED_NO_AUTOMATIC_REIMPORT'))
                continue
            try:
                rows,events=verified_jobs(self.controller,self.config['outputs'],[job])
                if not rows or rows[0]['status'] not in ('COMPLETE','FAILED'):continue
                row=rows[0]
                if row['source']!=self.config['source'] or row['kind'] not in ('synthetic_success','synthetic_failure'):
                    raise ValueError('SYNTHETIC_COMPLETION_SOURCE_REQUIRED')
                event=events[row['attempt_id']]
                proposal=None
                if next_job is not None and row['status']=='COMPLETE':
                    proposal={'job':next_job,'source':self.config['source'],
                              'predecessor':row['attempt_id'],'maximum_dispatches':1}
                with lock(r.state/'branch.lock'):
                    observation_path=r.state/('completion-observation-'+row['attempt_id']+'-'+r.config['source']+'.json')
                    if observation_path.exists():
                        if observation_path.is_symlink():raise ValueError('COMPLETION_OBSERVATION_SYMLINK')
                        observation=json.loads(observation_path.read_text())
                    else:
                        observation={'source':r.config['source'],'event_sha256':digest(event),
                            'day_first_observed':datetime.now(timezone.utc).date().isoformat(),
                            'rows':rows,'proposal':proposal,'evidence':{'completion':event,
                                'implementation':collect(r.root,{'kind':'handover_implementation',
                                    'purpose':'Review the actual bounded completion adapter and its authority limits.',
                                    'affected_task':job}),
                                'controller_process':current_process()}}
                        immutable(observation_path,encoded(observation))
                    if (observation['source']!=r.config['source'] or observation['event_sha256']!=digest(event)
                            or observation['proposal']!=proposal):raise ValueError('COMPLETION_OBSERVATION_CHANGED')
                    r.q.db.execute('BEGIN IMMEDIATE')
                    try:
                        if r.q.db.execute('SELECT 1 FROM completion_ingest WHERE job=?',(job,)).fetchone():
                            r.q.db.execute('COMMIT');continue
                        binding=r.enqueue_report(observation['day_first_observed'],observation['rows'],
                            {'trigger':'Verified synthetic completion '+job,
                             'event_sha256':digest(event),
                             'observation_timing':'Report day is the first verified observation, not an inferred execution date.',
                             'limits':'Configured synthetic successor only; scientific tasks keep their separate gates.'},
                            reviewer_evidence=observation['evidence'],
                            execution_proposal=proposal,trigger='verified-completion')
                        binding['kind']='astra_turn'
                        r.q.submit(binding)
                        r.q.db.execute('INSERT INTO completion_ingest VALUES(?,?,?,?)',
                            (row['attempt_id'],job,binding['id'],'QUEUED'))
                        r.q.db.execute('COMMIT')
                    except BaseException:r.q.db.execute('ROLLBACK');raise
                r.q.db.execute('DELETE FROM completion_blocks WHERE job=?',(job,))
            except (ValueError,KeyError,TypeError,OSError,sqlite3.Error):
                r.q.db.execute('INSERT OR REPLACE INTO completion_blocks VALUES(?,?)',
                    (job,'COMPLETION_EVIDENCE_RECONCILIATION_REQUIRED'))

    def finish(self,task,packet,answer):
        r=self.runtime
        row=r.q.db.execute('SELECT * FROM completion_ingest WHERE task=?',(task,)).fetchone()
        if not row:return
        proposal=packet.get('execution_proposal')
        if proposal is not None:
            expected={'job':self.config['pairs'].get(row['job']),'source':self.config['source'],
                      'predecessor':row['event'],'maximum_dispatches':1}
            if proposal!=expected or expected['job'] is None:raise ValueError('SYNTHETIC_PROPOSAL_CHANGED')
            choice=json.loads(answer)
            declined=(isinstance(choice,dict) and set(choice)=={'task_id','reason'}
                      and choice['task_id'] is None and isinstance(choice['reason'],str)
                      and 0<len(choice['reason'])<=1000)
            if not declined:choice=select_next(answer,proposal['job'])
            intent={'task':task,'event':row['event'],'proposal':proposal,'selection':choice}
            raw=encoded(intent).decode()
            immutable(r.state/(task+'.selected-dispatch.json'),raw.encode())
            r.q.db.execute('INSERT OR IGNORE INTO selected_dispatch(task,binding,status) VALUES(?,?,?)',
                (task,raw,'DECLINED' if declined else 'INTENT'))
            old=r.q.db.execute('SELECT * FROM selected_dispatch WHERE task=?',(task,)).fetchone()
            if old['binding']!=raw:raise ValueError('SYNTHETIC_DISPATCH_BINDING_CHANGED')
            if declined:
                r.q.db.execute("UPDATE selected_dispatch SET status='DECLINED' WHERE task=?",(task,))
            else:self.advance()
        r.q.db.execute("UPDATE completion_ingest SET status='PROCESSED' WHERE task=?",(task,))
        self.controller.db.execute("UPDATE wakes SET status='PROCESSED',reason='HANDOVER_REPORT_REVIEW_DISPOSITION_COMPLETE' WHERE id=?",(row['event'],))

    def advance(self):
        """Pause-aware idempotent submission; no model retry or new job identity."""
        r=self.runtime
        with lock(r.state/'admission.lock'):
            if r.q.status()['paused']:return
            for row in r.q.db.execute("SELECT * FROM selected_dispatch WHERE status='INTENT' ORDER BY rowid LIMIT 4").fetchall():
                attempt=row['attempts']+1
                r.q.db.execute('UPDATE selected_dispatch SET attempts=? WHERE task=?',(attempt,row['task']))
                try:
                    intent=json.loads(row['binding'])
                    if (r.state/(row['task']+'.selected-dispatch.json')).read_bytes()!=encoded(intent):
                        raise ValueError('DISPATCH_INTENT_CHANGED')
                    parent=r.q.db.execute('SELECT * FROM completion_ingest WHERE task=?',(row['task'],)).fetchone()
                    observed=self.controller.db.execute('SELECT id FROM linux_attempts WHERE job=?',(parent['job'],)).fetchone()
                    if not observed or observed[0]!=parent['event']:
                        raise ValueError('COMPLETION_IDENTITY_CHANGED_NO_AUTOMATIC_DISPATCH')
                    expected={'job':self.config['pairs'].get(parent['job']),'source':self.config['source'],
                              'predecessor':parent['event'],'maximum_dispatches':1}
                    if intent['proposal']!=expected or expected['job'] is None:
                        raise ValueError('SYNTHETIC_PROPOSAL_CHANGED')
                    select_next(json.dumps(intent['selection']),expected['job'])
                    # Persist before submission. Existing Controller.register
                    # rejects changed bindings and reuses the same job identity
                    # after a lost response, even if its child already completed.
                    self.controller.submit(expected['job'],expected['source'])
                    r.q.db.execute("UPDATE selected_dispatch SET status='SUBMITTED' WHERE task=?",(row['task'],))
                except (ValueError,KeyError,TypeError,OSError,sqlite3.Error):
                    if row['attempts']>=2:
                        r.q.db.execute("UPDATE selected_dispatch SET status='BLOCKED' WHERE task=?",(row['task'],))

"""Narrow OS-authenticated handover broker. No live grant is bundled here.

Protected service configuration/checkout/ledger/key ownership is the security
boundary. Scientific and model users must not own these paths or service code.
Remote Git credentials remain exclusively in the protected publisher identity.
"""
import argparse
from contextlib import nullcontext
import json
import hashlib
import fcntl
import os
from pathlib import Path
import socket
import struct
import re

from orchestrator.dispatch_limiter import GitLedger,admit_server,admit,reset,initialize,policy,validate_server_event
from orchestrator.git_publication import publish,scan
from orchestrator.phone_notifications import protected_read

REPOSITORY='https://github.com/Moroseui/concept-research-scout.git'
BRANCH='astra/infrastructure-milestone-record'


class Broker:
    def __init__(self,config):
        required={'mode','repository','branch','controller_uid','operator_uids','sources','ledger_repo','publication_root','policy','writer_config','model_mode','turn_root','max_model_turns'}
        if set(config) not in (required,required|{'activation_decision_sha256'}) or config['mode'] not in ('SYNTHETIC_FIXTURE','LIVE_APPROVED') or config['repository']!=REPOSITORY or config['branch']!=BRANCH:raise ValueError('PROTECTED_CONFIG_SCHEMA')
        if type(config['controller_uid']) is not int or config['controller_uid']<=0 or not config['operator_uids'] or config['controller_uid'] in config['operator_uids']:raise ValueError('DISTINCT_OPERATOR_REQUIRED')
        if config['model_mode'] not in ('DISABLED','SUPERVISED','GOVERNED') or type(config['max_model_turns']) is not int or not 0<=config['max_model_turns']<=4:raise ValueError('BOUNDED_MODEL_CONFIGURATION')
        if config['model_mode']=='GOVERNED':
            if config['mode']!='LIVE_APPROVED' or config['max_model_turns']!=0:
                raise ValueError('GOVERNED_MODE_REQUIRES_LIVE_PERMISSION')
            policy(config['policy'])
            if config['policy'].get('server_semantics')!='OPERATOR_AUTHORIZED_V1':
                raise ValueError('SERVER_ADMISSION_NOT_AUTHORIZED')
            if not isinstance(config.get('activation_decision_sha256'),str) or not re.fullmatch('[0-9a-f]{64}',config['activation_decision_sha256']):
                raise ValueError('SEPARATE_UNATTENDED_ACTIVATION_REQUIRED')
        if not isinstance(config['sources'],list) or not config['sources'] or len(config['sources'])>16:raise ValueError('BOUNDED_REVIEWED_SOURCES')
        if any(not isinstance(pin,str) or not re.fullmatch('[0-9a-f]{40}',pin) for pin in config['sources']):raise ValueError('REVIEWED_SOURCE_REQUIRED')
        roots=[Path(config[name]).resolve() for name in ('publication_root','ledger_repo','turn_root')]
        if any(a.is_relative_to(b) or b.is_relative_to(a) for i,a in enumerate(roots) for b in roots[i+1:]):
            raise ValueError('DISTINCT_PROTECTED_STATE_ROOTS_REQUIRED')
        if roots[0].is_relative_to(Path(__file__).resolve().parents[1]):
            raise ValueError('PUBLICATION_CACHE_MUST_NOT_BE_EXECUTION_SOURCE')
        self.config=config
        self.ledger=GitLedger(config['ledger_repo'],remote=config['mode']=='LIVE_APPROVED',expected_remote=REPOSITORY)

    def authentication(self):
        if self.config['mode']=='SYNTHETIC_FIXTURE':return nullcontext()
        from orchestrator.protected_writer import credentials
        return credentials(json.loads(protected_read(self.config['writer_config'])))

    def handle(self,request,peer_uid):
        if not isinstance(request,dict) or set(request)!={'operation','body'}:raise ValueError('BROKER_REQUEST_SCHEMA')
        if peer_uid!=self.config['controller_uid']:raise ValueError('BROKER_PEER_REFUSED')
        op=request['operation'];body=request['body']
        if not isinstance(body,dict):raise ValueError('BROKER_BODY_SCHEMA')
        if op=='status':
            if body!={}:raise ValueError('STATUS_BODY')
            with self.authentication():pin,state=self.ledger.read()
            return {'mode':self.config['mode'],'pin':pin,'sequence':state['sequence'],'count':state['count'],'halted':state['halted'],'day':state['day']}
        if op=='admit_server':
            if body.get('source') not in self.config['sources']:raise ValueError('REVIEWED_SOURCE_REQUIRED')
            with self.authentication():return admit_server(self.ledger,self.config['policy'],body)
        if op=='stage_status':return self.stage_status(body)
        if op=='model_stage':return self.model_stage(body)
        if op=='stage_candidate':
            import base64
            from orchestrator.publication_candidate import receive
            if set(body)!={'source','before','inventory','bundle_sha256','bundle_base64'}:
                raise ValueError('CANDIDATE_REQUEST_SCHEMA')
            raw=base64.b64decode(body['bundle_base64'],validate=True)
            # Fixed protected cache, no credentials and no remote publication.
            return receive(self.config['publication_root'],body['source'],body['before'],
                           body['inventory'],raw,body['bundle_sha256'])
        if op=='publish':
            if self.config['mode']!='LIVE_APPROVED':raise ValueError('LIVE_PUBLICATION_NOT_AUTHORIZED')
            policy(self.config['policy'])
            from orchestrator.publication_candidate import pins
            # Installed execution sources are distinct from new branch commits.
            # Every candidate still passes the complete audit and exact ref lease.
            pins(body.get('source'),body.get('audit_baseline') if body.get('operation')=='create' else body.get('before'))
            if body.get('destination')!=BRANCH or body.get('remote')!=REPOSITORY:raise ValueError('PUBLICATION_DESTINATION_REFUSED')
            keys={'operation','source','audit_baseline','baseline_ref','destination','remote','expected_destination'} if body.get('operation')=='create' else {'source','before','destination','remote'}
            if set(body)!=keys|{'inventory'}:raise ValueError('PUBLICATION_SCHEMA')
            # Checkout is a fixed protected import/cache path, never a request path.
            with self.authentication():return publish(Path(self.config['publication_root']),body,{k:body[k] for k in keys})
        raise ValueError('BROKER_OPERATION_REFUSED')

    def model_stage(self,body):
        from orchestrator.hosted_cycle import model_call,immutable,encoded
        from orchestrator.operations_report import private_root
        if self.config['model_mode'] not in ('SUPERVISED','GOVERNED') or os.getuid()!=0:raise ValueError('SUPERVISED_ROLE_LAUNCHER_REQUIRED')
        if set(body)!={'event','stage','packet','prompt'}:raise ValueError('MODEL_STAGE_SCHEMA')
        event=body['event'];stage=body['stage']
        validate_server_event(event)
        stages=['continuation','review','disposition']
        if stage not in stages or event.get('source') not in self.config['sources']:raise ValueError('MODEL_STAGE_SOURCE')
        scan('model-stage-request.json',json.dumps(body).encode())
        # Validate identity before forming a path, even if admission is unavailable.
        import re
        if not re.fullmatch('[0-9a-f]{64}',event.get('turn_id','')) or not re.fullmatch('[1-9][0-9]*',event.get('attempt','')):raise ValueError('TURN_ID')
        from orchestrator.remote_supervisor import checked_source
        checked_source(Path(__file__).resolve().parents[1],event['source'])
        root=private_root(self.config['turn_root'])
        with (root/'branch.lock').open('a') as gate:
            try:fcntl.flock(gate,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:raise ValueError('MODEL_WRITER_BUSY')
            folder=root/(event['turn_id']+'-'+event['attempt'])
            binding={'event':event,'packet_sha256':hashlib.sha256(encoded(body['packet'])).hexdigest()}
            if not folder.exists():
                retained=len(list(root.glob('*/binding.json')))
                if self.config['model_mode']=='SUPERVISED' and retained>=self.config['max_model_turns']:
                    raise ValueError('SUPERVISED_MODEL_BUDGET_EXHAUSTED')
                if retained>=10000:raise ValueError('MODEL_EVIDENCE_CAPACITY_REQUIRES_MAINTENANCE')
                folder.mkdir(mode=0o700)
                immutable(folder/'binding.json',encoded(binding))
                immutable(folder/'packet.json',encoded(body['packet']))
            if folder.is_symlink() or json.loads((folder/'binding.json').read_text())!=binding:raise ValueError('TURN_BINDING_CHANGED')
            immutable(folder/(stage+'.request.json'),encoded({'prompt_sha256':hashlib.sha256(body['prompt'].encode()).hexdigest()}))
            receipt_path=folder/(stage+'.receipt.json')
            if receipt_path.exists():return self.stage_status({'event':event,'stage':stage})
            if (folder/(stage+'.started.json')).exists():raise ValueError('UNCERTAIN_MODEL_RECONCILE_NO_RETRY')
            for prior in stages[:stages.index(stage)]:
                if self.stage_status({'event':event,'stage':prior})['status']!='COMPLETE':raise ValueError('PREDECESSOR_MODEL_RECEIPT_REQUIRED')
            with self.authentication():admission=admit_server(self.ledger,self.config['policy'],event)
            if admission['status']!='ADMITTED':return admission
            family='claude' if stage=='review' else 'astra'
            # The typed selector remains a tool-free model response. Only the
            # controller's fixed synthetic adapter can consume it; no command or
            # patient runner can be selected through this transport format.
            output_format='json' if stage=='disposition' and body['packet'].get('execution_proposal') is not None else 'markdown'
            answer,receipt=model_call(folder,stage,family,body['prompt'],output_format=output_format)
            return {'status':'COMPLETE','duplicate':False,'answer':answer,'receipt':receipt}

    def stage_status(self,body):
        """Retrieve original completion only. This path cannot invoke a model."""
        if set(body)!={'event','stage'}:raise ValueError('STAGE_STATUS_SCHEMA')
        event=body['event'];stage=body['stage'];validate_server_event(event)
        if stage not in ('continuation','review','disposition') or event['source'] not in self.config['sources']:raise ValueError('MODEL_STAGE_SOURCE')
        folder=Path(self.config['turn_root'])/(event['turn_id']+'-'+event['attempt'])
        if folder.is_symlink():raise ValueError('TURN_BINDING_CHANGED')
        if not folder.exists():return {'status':'NOT_OBSERVED_NO_RETRY'}
        binding_path=folder/'binding.json'
        if binding_path.is_symlink() or json.loads(binding_path.read_text())['event']!=event:raise ValueError('TURN_BINDING_CHANGED')
        path=folder/(stage+'.receipt.json')
        if not path.exists():
            status='UNCERTAIN_MODEL_RECONCILE_NO_RETRY' if (folder/(stage+'.started.json')).exists() else 'NOT_STARTED_RECONCILIATION_REQUIRED'
            return {'status':status}
        if path.is_symlink():raise ValueError('MODEL_RECEIPT_CHANGED')
        receipt=json.loads(path.read_text())
        for suffix,key in [('.stdout','stdout_sha256'),('.stderr','stderr_sha256'),('.input.md','input_sha256'),('.md','answer_sha256'),('.operating-context.json','operating_context_sha256')]:
            file=folder/(stage+suffix)
            if file.is_symlink() or hashlib.sha256(file.read_bytes()).hexdigest()!=receipt[key]:raise ValueError('MODEL_RECEIPT_CHANGED')
        return {'status':'COMPLETE','duplicate':True,'answer':(folder/(stage+'.md')).read_text(),'receipt':receipt}

    def actions_admission(self,artifact,verified_run):
        # Trusted Actions API collector supplies verified_run; requester JSON does
        # not establish repo/run provenance. No run text or artifact is executed.
        required={'repository_id','run_id','attempt','source','branch','workflow_sha256'}
        if set(artifact)!=required or artifact!=verified_run:raise ValueError('ACTIONS_PROVENANCE_REQUIRED')
        if artifact['repository_id']!=1323461276 or artifact['source'] not in self.config['sources']:raise ValueError('ACTIONS_SOURCE_REFUSED')
        with self.authentication():return admit(self.ledger,self.config['policy'],{k:artifact[k] for k in ('run_id','attempt','source','branch')})

    def operator(self,operation,body):
        uid=os.getuid()
        if uid not in self.config['operator_uids']:raise ValueError('OPERATOR_OS_IDENTITY_REQUIRED')
        actor='ssh-uid:'+str(uid)
        if operation=='reset':
            if set(body)!={'expected_sequence','decision_ref','policy_sha256'}:raise ValueError('RESET_SCHEMA')
            if body['policy_sha256']!=hashlib.sha256(json.dumps(self.config['policy'],sort_keys=True).encode()).hexdigest():raise ValueError('RESET_POLICY_MOVED')
            with self.authentication():return reset(self.ledger,self.config['policy'],{'actor':actor,'role':'operator','expected_sequence':body['expected_sequence'],'decision_ref':body['decision_ref']})
        if operation=='initialize':
            if set(body)!={'decision_ref'}:raise ValueError('INITIALIZE_SCHEMA')
            previous=self.ledger.allow_initialization
            try:
                self.ledger.allow_initialization=True
                with self.authentication():return initialize(self.ledger,self.config['policy'],{'actor':actor,'role':'operator',**body})
            finally:self.ledger.allow_initialization=previous
        raise ValueError('OPERATOR_OPERATION_REFUSED')


def exchange(broker,connection):
    """One bounded request; a disconnected client must not kill the broker."""
    try:
        connection.settimeout(10)
        _,uid,_=struct.unpack('3i',connection.getsockopt(socket.SOL_SOCKET,socket.SO_PEERCRED,12))
        raw=b''
        while b'\n' not in raw and len(raw)<=1500000:
            data=connection.recv(65536)
            if not data:break
            raw+=data
        if len(raw)>1500000 or not raw.endswith(b'\n') or raw.count(b'\n')!=1:raise ValueError('BOUNDED_REQUEST_REQUIRED')
        request=json.loads(raw);scan('broker-request.json',raw)
        response=broker.handle(request,uid)
        value=json.dumps(response).encode();scan('broker-response.json',value)
    except Exception as error:
        # Never echo request data or arbitrary exception text. Named codes only.
        import re
        reason=str(error)
        if not re.fullmatch('[A-Z][A-Z0-9_]{1,100}',reason):reason='BROKER_FAILURE_PRESERVED'
        value=json.dumps({'status':'REFUSED','reason':reason,
            'next_action':'Inspect protected evidence and recover original receipts before retrying.'}).encode()
    try:connection.sendall(value+b'\n')
    except OSError:pass  # Original completion persists even when transport fails.


def serve(config_path,socket_path):
    broker=Broker(json.loads(protected_read(config_path)))
    # systemd owns the socket across service restarts; no unlink-and-rebind race.
    activated=os.environ.get('LISTEN_PID')==str(os.getpid()) and os.environ.get('LISTEN_FDS')=='1'
    if activated:
        server=socket.socket(fileno=3)
        if server.family!=socket.AF_UNIX or server.getsockname()!=socket_path:raise ValueError('ACTIVATED_SOCKET_MISMATCH')
    else:
        raise ValueError('SYSTEMD_SOCKET_ACTIVATION_REQUIRED')
    with server:
        while True:
            connection,_=server.accept()
            with connection:exchange(broker,connection)


